describe('Login with Invalid Password', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/login');
  });

  it('should display error message when submitting with wrong password', () => {
    cy.get('#username').type('tomsmith');
    cy.get('#password').type('wrongpassword');
    cy.get('button[type="submit"]').click();

    cy.url().should('include', '/login');
    cy.get('.flash.error').should('be.visible');
    cy.get('.flash.error').should('contain', 'Your password is invalid!');
  });

  it('should remain on login page and show error for empty password field', () => {
    cy.get('#username').type('tomsmith');
    cy.get('button[type="submit"]').click();

    cy.url().should('include', '/login');
    cy.get('.flash.error').should('be.visible');
  });

  it('should display error message when submitting with empty username and wrong password', () => {
    cy.get('#password').type('wrongpassword');
    cy.get('button[type="submit"]').click();

    cy.url().should('include', '/login');
    cy.get('.flash.error').should('be.visible');
  });

  it('should allow user to correct password after initial failure', () => {
    cy.get('#username').type('tomsmith');
    cy.get('#password').type('wrongpassword');
    cy.get('button[type="submit"]').click();

    cy.get('.flash.error').should('be.visible');

    cy.get('#password').clear().type('SuperSecretPassword!');
    cy.get('button[type="submit"]').click();

    cy.url().should('include', '/secure');
    cy.get('.flash.success').should('contain', 'You logged into a secure area!');
  });
});
